function validate([coins, k]) {
  if (!Array.isArray(coins) || coins.length < 1 || coins.length > 15) return 'coins needs 1 to 15 values.';
  if (coins.some(c => !Number.isInteger(c) || c < 1 || c > 25)) return 'Each coin is an integer from 1 to 25.';
  if (new Set(coins).size !== coins.length) return 'The coins must all be different.';
  if (!Number.isInteger(k) || k < 1 || k > 2000000000) return 'k is between 1 and 2 * 10^9.';
  return null;
}

