function findKthSmallest(coins, k) {
  const gcd = (a, b) => {
    while (b !== 0) {
      [a, b] = [b, a % b];
    }
    return a;
  };
  const subsets = 1 << coins.length;
  const lcm = new Array(subsets).fill(1);
  const sign = new Array(subsets).fill(-1);
  for (let mask = 1; mask < subsets; mask++) {
    const lowBit = mask & -mask;
    const rest = mask ^ lowBit;
    const coin = coins[31 - Math.clz32(lowBit)];
    lcm[mask] = (lcm[rest] / gcd(lcm[rest], coin)) * coin;
    sign[mask] = -sign[rest];
  }
  const countUpTo = (x) => {
    let count = 0;
    for (let mask = 1; mask < subsets; mask++) {
      count += sign[mask] * Math.floor(x / lcm[mask]);
    }
    return count;
  };
  let left = 1;
  let right = Math.min(...coins) * k;
  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (countUpTo(mid) >= k) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  return left;
}

