function findKthSmallest(coins, k) {
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const period = coins.reduce((acc, c) => (acc / gcd(acc, c)) * c, 1);
  if (period <= 2000000) {
    // Reachable amounts repeat with the LCM of all coins as the period.
    const inPeriod = [];
    for (let amount = 1; amount <= period; amount++) {
      if (coins.some(c => amount % c === 0)) inPeriod.push(amount);
    }
    const full = Math.floor((k - 1) / inPeriod.length);
    return full * period + inPeriod[(k - 1) % inPeriod.length];
  }
  let found = 0;
  for (let amount = 1; ; amount++) {
    if (coins.some(c => amount % c === 0)) {
      found++;
      if (found === k) return amount;
    }
  }
}

