function generate(rand, size) {
  const pick = (count, top) => {
    const pool = Array.from({ length: top }, (_, i) => i + 1);
    for (let i = pool.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    return pool.slice(0, count);
  };
  if (size === 'large') {
    const n = 10 + Math.floor(rand() * 6);
    const k = 1000000000 + Math.floor(rand() * 1000000001);
    return [pick(n, 25), k];
  }
  const top = rand() < 0.5 ? 10 : 25;
  const n = 1 + Math.floor(rand() * 5);
  const k = 1 + Math.floor(rand() * 60);
  return [pick(n, top), k];
}
